package com.resumeanalyzer.service.analysis;

import org.springframework.stereotype.Component;

import java.util.ArrayList;
import java.util.Arrays;
import java.util.List;
import java.util.Locale;
import java.util.Set;
import java.util.regex.Pattern;

/**
 * Deterministic, rule-based ATS and formatting/readability checks.
 *
 * Every check here is a plain, reproducible fact derivable from the
 * resume's extracted text (Phase 2) and the skill-matching result (Phase
 * 3) - nothing is inferred, guessed, or generated by a model. If a check
 * cannot be reliably determined from the available text (e.g. true
 * visual layout, columns, fonts - lost during PDFBox/POI text
 * extraction), it is simply not attempted here, per the project's
 * "never fabricate" requirement.
 */
@Component
public class AtsAnalyzer {

    private static final Pattern EMAIL_PATTERN = Pattern.compile("[\\w.+-]+@[\\w-]+\\.[\\w.-]+");
    private static final Pattern PHONE_PATTERN = Pattern.compile("(\\+?\\d[\\d\\-. ()]{8,}\\d)");
    private static final List<String> STANDARD_SECTION_HEADINGS = List.of(
            "experience", "education", "skills", "summary", "projects", "certifications");

    private static final int MIN_WORD_COUNT = 50;
    private static final int MAX_WORD_COUNT = 2000;
    private static final int MAX_AVERAGE_WORDS_PER_SENTENCE = 40;
    private static final double MAX_UPPERCASE_LETTER_RATIO = 0.3;

    /**
     * The result of analyzing a single resume, independent of any
     * specific job description.
     */
    public record AtsAnalysisResult(List<String> atsIssues, List<String> formattingIssues) {
    }

    public AtsAnalysisResult analyze(String resumeText, Set<String> jobRequiredSkills, Set<String> matchedSkills) {
        List<String> atsIssues = new ArrayList<>();
        List<String> formattingIssues = new ArrayList<>();

        if (resumeText == null || resumeText.isBlank()) {
            // Defensive only: Phase 2 never persists a Resume with blank
            // extracted text, so this should not occur in practice.
            atsIssues.add("No resume text is available to analyze.");
            return new AtsAnalysisResult(atsIssues, formattingIssues);
        }

        String[] words = resumeText.trim().split("\\s+");
        int wordCount = words.length;

        if (!EMAIL_PATTERN.matcher(resumeText).find()) {
            atsIssues.add("No email address detected in the resume; ATS systems typically require a visible contact email.");
        }

        if (!PHONE_PATTERN.matcher(resumeText).find()) {
            atsIssues.add("No phone number detected in the resume.");
        }

        String lowerCaseText = resumeText.toLowerCase(Locale.ROOT);
        boolean hasStandardHeading = STANDARD_SECTION_HEADINGS.stream().anyMatch(lowerCaseText::contains);
        if (!hasStandardHeading) {
            atsIssues.add("No standard section headings (e.g. Experience, Education, Skills) detected; "
                    + "ATS parsers rely on these to categorize resume content.");
        }

        if (wordCount < MIN_WORD_COUNT) {
            atsIssues.add("Resume content is very short (" + wordCount + " words), "
                    + "which may indicate incomplete content or an extraction issue.");
        }

        if (jobRequiredSkills != null && !jobRequiredSkills.isEmpty() && (matchedSkills == null || matchedSkills.isEmpty())) {
            atsIssues.add("None of the job description's identified skills were found in the resume, "
                    + "which may cause ATS keyword filters to reject this resume.");
        }

        if (wordCount > MAX_WORD_COUNT) {
            formattingIssues.add("Resume content is unusually long (" + wordCount + " words), "
                    + "which may exceed typical ATS/recruiter attention span.");
        }

        double averageWordsPerSentence = averageWordsPerSentence(resumeText, wordCount);
        if (averageWordsPerSentence > MAX_AVERAGE_WORDS_PER_SENTENCE) {
            formattingIssues.add("Some sentences appear very long (average of "
                    + Math.round(averageWordsPerSentence) + " words per sentence), "
                    + "which can hurt both ATS parsing and human readability.");
        }

        double uppercaseRatio = uppercaseLetterRatio(resumeText);
        if (uppercaseRatio > MAX_UPPERCASE_LETTER_RATIO) {
            formattingIssues.add("Excessive use of capital letters detected ("
                    + Math.round(uppercaseRatio * 100) + "% of letters), "
                    + "which may appear unprofessional or hinder ATS parsing.");
        }

        return new AtsAnalysisResult(atsIssues, formattingIssues);
    }

    private double averageWordsPerSentence(String text, int wordCount) {
        String[] sentences = text.split("[.!?]+");
        long nonBlankSentences = Arrays.stream(sentences).filter(s -> !s.isBlank()).count();
        if (nonBlankSentences == 0) {
            return 0.0;
        }
        return (double) wordCount / nonBlankSentences;
    }

    private double uppercaseLetterRatio(String text) {
        long letters = text.chars().filter(Character::isLetter).count();
        if (letters == 0) {
            return 0.0;
        }
        long uppercase = text.chars().filter(Character::isUpperCase).count();
        return (double) uppercase / letters;
    }
}
